'use strict';
const axes=[['R','🔧','만들고 다루기','실제로 움직이거나 작동하는 것을 다루는 활동'],['I','🔍','궁금한 것 탐구하기','관찰·비교로 이유를 찾는 활동'],['A','🎨','새롭게 표현하기','나만의 글·화면·이야기를 만드는 활동'],['S','🤝','사람 이해하고 돕기','듣고 설명하며 사람을 돕는 활동'],['E','🚀','제안하고 이끌기','아이디어를 제안하고 함께 추진하는 활동'],['C','📋','정리하고 정확히 하기','자료·일정을 정리하고 오류를 찾는 활동']];
const items=[
['고장 난 물건의 원인을 찾아 작동하게 해보고 싶어.','여러 제품의 성능·가격을 비교해 차이의 이유를 알고 싶어.','앱 화면이나 포스터를 내 취향으로 바꿔보고 싶어.','친구가 어려워하는 내용을 이해하기 쉽게 설명하고 싶어.','친구들의 의견을 모아 함께 할 일을 제안하고 싶어.','복잡한 메모를 보기 쉬운 표나 목록으로 정리하고 싶어.'],
['설명서를 보면서 간단한 모형이나 장치를 조립하고 싶어.','실험 결과가 예상과 다르면 왜 그런지 더 알아보고 싶어.','짧은 영상·글·음악으로 내 생각을 표현하고 싶어.','상대가 무엇 때문에 불편한지 이야기를 듣고 싶어.','누구에게 어떤 제품이 필요한지 생각하고 추천하고 싶어.','계획표에서 빠진 일정이나 겹치는 일을 찾아보고 싶어.'],
['식물이나 재료를 직접 다루며 변화를 확인하고 싶어.','건강·환경·사회 문제의 원인을 자료로 살펴보고 싶어.','익숙한 이야기의 결말을 새롭게 만들어보고 싶어.','처음 배우는 사람을 위한 친절한 안내를 만들고 싶어.','작은 행사를 기획하고 역할을 나누어 진행하고 싶어.','자료의 숫자·출처가 맞는지 차근차근 확인하고 싶어.'],
['공간이나 도구를 실제로 써보며 더 편하게 개선하고 싶어.','주장을 들으면 근거와 다른 설명도 찾아보고 싶어.','같은 정보를 더 눈에 띄고 재미있게 전달하고 싶어.','팀에서 누군가 어려움을 겪으면 함께 해결하고 싶어.','내 아이디어의 장점을 설명하고 의견을 받아 개선하고 싶어.','반복되는 일을 일정한 순서로 처리하는 방법을 만들고 싶어.']];
const questions=items.flatMap(row=>row.map((text,i)=>({axis:axes[i][0],text})));
const mapping={ai:['I','C'],robots:['R','I'],health:['I','S'],energy:['R','I'],security:['I','C'],creative:['A','E'],business:['E','C'],education:['S','A'],city:['R','E'],food:['R','I']};
const labels=['😕 별로 하고 싶지 않아','🙁 조금 덜 끌려','😐 보통이야','🙂 해보고 싶어','🤩 정말 해보고 싶어','🐾 경험이 없어서 모르겠어'];
const key='compass-know-me-v1';let answers=Array(24).fill(undefined),index=-1,note='';
try{const saved=JSON.parse(localStorage.getItem(key)||'null');if(saved&&Array.isArray(saved.answers)){answers=questions.map((_,i)=>{const v=saved.answers[i];return v===null?null:Number.isInteger(v)&&v>=1&&v<=5?v:undefined});index=Number.isInteger(saved.index)&&saved.index>=-1&&saved.index<=24?saved.index:-1;note=typeof saved.note==='string'?saved.note.slice(0,600):''}}catch{}
function save(){try{localStorage.setItem(key,JSON.stringify({answers:answers.map(v=>v===undefined?'unanswered':v),index,note}))}catch{}}
function esc(s){return String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function profile(values){return axes.map(a=>{const vs=values.filter((v,i)=>questions[i].axis===a[0]&&Number.isInteger(v));return {axis:a,count:vs.length,mean:vs.length?vs.reduce((s,v)=>s+v,0)/vs.length:null}})}
function friend(text){return `<div class="friend"><img src="shiro-letter.jpg" alt="편지를 물고 온 흰둥이"><div class="bubble"><span class="tag">🐶 흰둥이가 물어봐요</span><p>${text}</p></div></div>`}
function intro(){return `${friend('승준아, 너는 어떤 순간이 제일 재밌어? 정답은 없어. 지금 마음에 가까운 걸 골라봐!')}<h1>내가 좋아하는 건? ✨</h1><p>24가지 질문으로 좋아하는 활동을 찾아보자.<br>공부를 잘하는지 평가하지 않아. 잘 모르겠어도 괜찮아!</p><div class="note">⏱ 약 5–7분 예상 · 한 번에 한 질문 · 중간 저장<br>🧭 질문 탐험은 기존 관심 탐색기와 별도예요.</div><img class="art" src="cozy-study.jpg" alt="잠옷을 입고 공부하는 짱구와 흰둥이"><div class="actions"><button class="primary" data-start>${answers.some(v=>v!==undefined)?'이어서 나 알아보기 →':'흰둥이랑 시작하기 →'}</button><a href="/#career-lab">기존 관심 탐색기 열기</a></div>`}
function question(){const q=questions[index];return `<div class="small">🐾 ${index+1} / 24 · 답한 질문 ${answers.filter(v=>v!==undefined).length}개</div><progress value="${index+1}" max="24" aria-label="질문 진행"></progress>${friend('잘하는 것보다, 해보고 싶은 마음을 골라줘.')}<h1 id="question-title">${q.text}</h1><div class="choices" role="group" aria-labelledby="question-title">${labels.map((l,i)=>`<button data-answer="${i===5?'unknown':i+1}" aria-pressed="${answers[index]===(i===5?null:i+1)}">${l}</button>`).join('')}</div><div class="actions"><button data-prev>${index===0?'처음으로':'← 이전'}</button><button class="primary" data-next ${answers[index]===undefined?'disabled':''}>${index===23?'내 취향 만나보기 ✨':'다음 질문 →'}</button></div><p class="small">답은 자동 저장돼. 언제든 바꿀 수 있어.</p>`}
function result(){const p=profile(answers),eligible=p.filter(x=>x.count>=3).sort((a,b)=>b.mean-a.mean),enough=p.every(x=>x.count>=3),top=enough?eligible.filter(x=>x.mean>=eligible[Math.min(2,eligible.length-1)].mean):[],allSimilar=enough&&eligible[0].mean-eligible[5].mean<.5;const ranked=enough?Object.entries(mapping).map(([d,c])=>({d,score:c.reduce((s,a)=>s+p.find(x=>x.axis[0]===a).mean,0)/c.length})).sort((a,b)=>b.score-a.score):[];const selected=ranked.slice(0,3);return `${friend(enough?'네가 고른 마음을 모아봤어. 이건 지금의 취향 지도야. 직접 해보면 달라질 수 있어!':'아직 모르는 활동이 많아도 괜찮아. 작은 경험부터 해보자!')}<h1>${!enough?'아직 여러 방향이 열려 있어요 🌱':allSimilar?'여러 활동에 마음이 열려 있어요 🌈':'이런 순간이 끌렸구나 ✨'}</h1><p>${enough?'상위 관심은 '+top.map(x=>x.axis[1]+' '+x.axis[2]).join(' · '):'6가지 관심마다 숫자 답변이 3개 이상일 때 비교해요. 이 기준은 앱의 탐색 규칙이며 검증된 검사 기준은 아니에요.'}</p><section class="cards">${p.map(x=>`<div class="axis"><strong>${x.axis[1]} ${x.axis[2]}</strong><span>${x.count?x.mean.toFixed(1)+' / 5':'아직 모름'} · ${x.count}/4답</span></div>`).join('')}</section><p class="small">5점 선택의 평균이에요. 능력·백분위·취업 성공률이 아니에요. 모름은 계산에서 제외해요.${enough?' 같은 평균은 동점이며 나열 순서에 우열이 없어요.':''}</p><details><summary>🗣 내가 해보고 싶다고 고른 활동</summary>${questions.filter((q,i)=>answers[i]>=4).map(q=>`<p>✓ ${q.text}</p>`).join('')||'<p>아직 뚜렷하게 고른 활동이 없어. 작은 체험부터 해보자.</p>'}</details><h2>🔮 미래에서 만나볼 일</h2><p>${enough?'서로 다른 3개 분야의 탐색 예시예요. 같은 점수의 분야도 있어요. 모든 직업을 평가한 추천은 아니에요.':'점수로 추천을 정하지 않고, 서로 다른 활동을 경험할 예시를 보여줘요.'}</p><div class="cards">${(enough?selected:[{d:'robots'},{d:'creative'},{d:'education'}]).map(x=>{const c=quizCareers[x.d][0];return `<article class="card"><h3>${axes.find(a=>a[0]===mapping[x.d][0])[1]} ${esc(c[0])}</h3><p>${esc(c[1])}</p><details><summary>공부·학과·30분 체험 보기 →</summary><p><strong>🎓 공부와 학과</strong><br>${esc(c[3])}</p><p><strong>🕒 먼저 30분</strong><br>${esc(c[4])}</p><p><strong>🤖 AI가 도울 업무</strong><br>${esc(c[5])}</p><p><strong>💡 사람이 연습할 판단</strong><br>${esc(c[6])}</p><p>연결 이유: ${mapping[x.d].map(a=>axes.find(t=>t[0]===a)[2]).join(' + ')} 활동을 연결한 자체 예시 규칙.</p><a href="/#career-lab">기존 탐색기에서 30개 직업 비교하기 →</a></details></article>`}).join('')}</div><div class="note">🌱 자동화 도구가 바뀌어도 문제를 정의하고, 근거를 확인하고, 사람에게 설명하는 연습을 이어가자. 미래 직업 수요와 합격을 보장하지 않아요.</div><h2>📝 직접 해보고 내 마음 기록하기</h2><p>서로 다른 활동 2개를 30분씩 해보고, 재미·어려움·다시 하고 싶은 마음을 적어봐.</p><label for="note">내 체험 메모</label><textarea id="note" maxlength="600" placeholder="재밌었던 점 / 어려웠던 점 / 다음에 해보고 싶은 것">${esc(note)}</textarea><div class="actions"><a class="action" href="/#career-lab">직업과 준비 더 알아보기 →</a><button data-edit>답 다시 살펴보기</button><button data-reset>질문 기록 지우기</button></div><details><summary>탐색 방식과 공식 자료</summary><p>RIASEC의 6가지 직업 흥미 구분을 참고해 새로 쓴 24개 질문이에요. O*NET 공식 문항·점수·직업 매칭을 사용한 검사가 아니며 심리측정 타당성이 검증되지 않았어요. 직업 분야는 관심 2개 평균으로 정렬하고, 같은 점수는 고정된 목록 순서로 보여줘요. 3분야의 첫 직업을 예시로 보여주므로 다른 직업도 비교해보세요.</p><a href="https://www.onetcenter.org/IP.html" target="_blank" rel="noopener">O*NET 흥미 분류 근거 ↗</a><br><a href="https://www.career.go.kr/cloud/" target="_blank" rel="noopener">커리어넷 공식 검사·직업 정보 ↗</a></details>`}
function renderQuiz(focus=false){document.querySelector('#quiz').innerHTML=index<0?intro():index<24?question():result();if(focus){document.querySelector('#quiz').focus();window.scrollTo(0,0)}}
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.hasAttribute('data-start')){const missing=answers.findIndex(v=>v===undefined);index=missing<0?24:missing}else if(b.dataset.answer){answers[index]=b.dataset.answer==='unknown'?null:Number(b.dataset.answer);save();renderQuiz();document.querySelector(`[data-answer="${b.dataset.answer}"]`).focus();return}else if(b.hasAttribute('data-next')&&answers[index]!==undefined)index++;else if(b.hasAttribute('data-prev'))index--;else if(b.hasAttribute('data-edit'))index=0;else if(b.hasAttribute('data-reset')){answers=Array(24).fill(undefined);note='';index=-1}else return;save();renderQuiz(true)});
document.addEventListener('input',e=>{if(e.target.id==='note'){note=e.target.value.slice(0,600);save()}});renderQuiz();
